INSERT INTO `setupliteraturereview` VALUES (1,100102,'<p>MNBH,GJ</p>','2025-08-15 17:45:41.542315','2025-08-16 06:55:16.814732'),(2,100103,'<figure class=\"table\"><table><tbody><tr><td>BIOMETRY</td><td>MEASUREMENT</td><td>GESTATIONAL AGE&nbsp;</td></tr><tr><td>BPD</td><td>11.25</td><td>17 WEEKS , 4 DAYS&nbsp;</td></tr><tr><td>HC&nbsp;</td><td>138.38</td><td>20 WEEKS , 5 DAYS&nbsp;</td></tr><tr><td>AC 1</td><td>389</td><td>40 WEEKS, 6 DAYS&nbsp;</td></tr></tbody></table></figure>','2025-08-15 17:59:54.657819','2026-10-05 12:01:08.308305'),(3,100104,NULL,'2025-08-16 12:11:46.185726',NULL),(4,100105,NULL,'2025-08-16 12:12:41.076579',NULL),(5,100106,NULL,'2025-08-16 12:13:06.721076',NULL),(6,100107,'FHNJHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH','2025-08-16 12:13:55.407878','2026-10-13 14:49:15.654065'),(7,100108,NULL,'2025-08-16 12:16:40.762250',NULL),(8,100109,NULL,'2025-08-16 12:17:21.515774',NULL),(9,100110,NULL,'2025-08-16 12:17:36.873304',NULL),(10,100111,NULL,'2025-08-16 12:17:44.556556',NULL),(11,100112,NULL,'2025-08-16 12:18:50.116796',NULL),(12,100113,'<h4>KEY:&nbsp;</h4><p>CONT. - CONTROL&nbsp;</p><p>PAT. - PATIENT&nbsp;</p><p>INR - INTERNATIONAL NORMALISED RATIO</p>','2025-08-16 12:19:13.849295','2025-08-16 20:46:29.313437'),(13,100114,NULL,'2025-08-16 12:24:06.959067',NULL),(14,100115,NULL,'2025-08-16 12:24:17.892280',NULL),(15,100116,NULL,'2025-08-16 12:24:28.958080',NULL),(16,100117,NULL,'2025-08-16 12:25:48.803296',NULL),(17,100118,NULL,'2025-08-16 12:26:10.250106',NULL),(18,100119,NULL,'2025-08-16 12:26:26.389553',NULL),(19,100120,NULL,'2025-08-16 12:26:39.016462',NULL),(20,100121,NULL,'2025-08-16 12:26:51.787740',NULL),(21,100122,'<p>This assay is a quantitative assay used for monitoring patients on therapy and not qualitative assay used for screening. Hence a Target Not Detected result should not be considered as HBV status Negative for the patient. Quantitative viral load results are best reflected when reported using log transformed units. Logarithmic expression best reflects the process of viral replication and is less subject to over interpretation of non-clinically significant (minor) changes.&nbsp;</p><p><strong>Instrument Name:</strong> Rotor-Gene Q MDX 5 Plex HRM | Software Version: 2.3.5&nbsp;</p><p>Results must be interpreted within the context of relevant clinical and laboratory findings.&nbsp;</p><p>HBV DNA was extracted using the TRUPCR Viral nucleic acid extraction kit with amplification, detection and analysis performed using the Rotor-Gene Q MDX 5 Plex HRM. The linear range of the assay is 2.5 IU/mL to 1 x 10^8 IU/mL, and the limit of detection (LoD) of the assay is 2.5 IU/mL.&nbsp;</p><ol><li>&lt;2.5 IU/mL, result is valid. Quantitation is not possible since the quantitative result is below the linear range value of the assay. Reproducibility of the positive result is not guaranteed;&nbsp;</li><li>&gt;1 x 10^8 IU/mL result is valid. HBV DNA is detected at a concentration &gt;1 x 10^8 IU/mL. Quantitation is not possible since the quantitative result is above the linear range of the assay.</li></ol>','2025-08-16 12:27:04.680713','2025-09-09 12:22:11.165279'),(22,100123,NULL,'2025-08-16 12:27:17.683361',NULL),(23,100124,NULL,'2025-08-16 12:27:29.251573',NULL),(24,100125,NULL,'2025-08-16 12:28:01.208211',NULL),(25,100126,NULL,'2025-08-16 12:28:16.876708',NULL),(26,100127,NULL,'2025-08-16 12:28:49.436527',NULL),(27,100128,NULL,'2025-08-16 12:30:58.999290',NULL),(28,100129,NULL,'2025-08-16 12:31:09.937900',NULL),(29,100130,NULL,'2025-08-16 12:31:22.011081',NULL),(30,100131,NULL,'2025-08-16 12:31:52.467614',NULL),(31,100132,NULL,'2025-08-16 12:32:03.075990',NULL),(32,100133,NULL,'2025-08-16 12:32:27.860342',NULL),(33,100134,NULL,'2025-08-16 12:32:50.170576',NULL),(34,100135,NULL,'2025-08-16 12:33:05.118224',NULL),(35,100136,'<figure class=\"table\"><table><thead><tr><th><strong>Test</strong></th><th><strong>Literature Review / Clinical Notes</strong></th></tr></thead><tbody><tr><td>HVS Culture &amp; Sensitivity</td><td>Vaginal discharge</td></tr><tr><td>HVS Culture &amp; Sensitivity</td><td>Abnormal vaginal discharge</td></tr><tr><td>HVS Culture &amp; Sensitivity</td><td>Foul-smelling vaginal discharge</td></tr><tr><td>HVS Culture &amp; Sensitivity</td><td>Recurrent vaginal discharge</td></tr><tr><td>HVS Culture &amp; Sensitivity</td><td>Vaginal itching and discharge</td></tr><tr><td>HVS Culture &amp; Sensitivity</td><td>Vaginal irritation</td></tr><tr><td>HVS Culture &amp; Sensitivity</td><td>Suspected vaginal infection</td></tr><tr><td>HVS Culture &amp; Sensitivity</td><td>Suspected bacterial vaginosis</td></tr><tr><td>HVS Culture &amp; Sensitivity</td><td>Suspected vulvovaginal candidiasis</td></tr><tr><td>HVS Culture &amp; Sensitivity</td><td>Recurrent vulvovaginal infection</td></tr><tr><td>HVS Culture &amp; Sensitivity</td><td>Lower abdominal pain with vaginal discharge</td></tr><tr><td>HVS Culture &amp; Sensitivity</td><td>Post-treatment persistent vaginal discharge</td></tr><tr><td>HVS Culture &amp; Sensitivity</td><td>Recurrent symptoms despite previous treatment</td></tr><tr><td>HVS Culture &amp; Sensitivity</td><td>Assessment of vaginal infection and antimicrobial susceptibility</td></tr><tr><td>HVS Culture &amp; Sensitivity</td><td><strong>Routine investigation</strong></td></tr></tbody></table></figure>','2025-08-16 12:33:15.882885','2026-10-05 09:05:28.091147'),(36,100137,NULL,'2025-08-16 12:37:41.297531',NULL),(37,100138,NULL,'2025-08-16 12:37:55.018045',NULL),(38,100139,NULL,'2025-08-16 12:38:10.701544',NULL),(39,100140,NULL,'2025-08-16 12:38:37.925507',NULL),(40,100141,NULL,'2025-08-16 12:38:54.620662',NULL),(41,100142,NULL,'2025-08-16 12:39:06.800016',NULL),(42,100143,NULL,'2025-08-16 12:39:13.821218',NULL),(43,100144,NULL,'2025-08-16 12:39:29.748536',NULL),(44,100145,NULL,'2025-08-16 12:39:42.129947',NULL),(45,100146,NULL,'2025-08-16 12:39:51.822787',NULL),(46,100147,NULL,'2025-08-16 12:40:03.022103',NULL),(47,100148,NULL,'2025-08-16 12:40:11.367357',NULL),(48,100149,NULL,'2025-08-16 12:40:24.740094',NULL),(49,100150,NULL,'2025-08-16 12:40:44.797680',NULL),(50,100151,NULL,'2025-08-16 12:44:27.702496',NULL),(51,100152,NULL,'2025-08-16 12:44:37.044201',NULL),(52,100153,NULL,'2025-08-16 12:44:58.035078',NULL),(53,100154,NULL,'2025-08-16 12:45:11.999733',NULL),(54,100155,NULL,'2025-08-16 12:45:21.662667',NULL),(55,100156,NULL,'2025-08-16 12:45:27.107629',NULL),(56,100157,NULL,'2025-08-16 12:45:36.954301',NULL),(57,100158,NULL,'2025-08-16 12:45:45.834987',NULL),(58,100159,NULL,'2025-08-16 12:46:39.001530',NULL),(59,100160,NULL,'2025-08-16 12:47:01.366220',NULL),(60,100161,NULL,'2025-08-16 12:47:12.994835',NULL),(61,100162,NULL,'2025-08-16 12:47:23.536435',NULL),(62,100163,NULL,'2025-08-16 12:47:30.111821',NULL),(63,100164,NULL,'2025-08-16 12:48:36.551648',NULL),(64,100165,NULL,'2025-08-16 12:48:51.366494',NULL),(65,100166,NULL,'2025-08-16 12:49:00.229377',NULL),(66,100167,NULL,'2025-08-16 12:49:09.017468',NULL),(67,100168,NULL,'2025-08-16 12:49:50.019767',NULL),(68,100169,NULL,'2025-08-16 12:50:03.592107',NULL),(69,100170,NULL,'2025-08-16 12:50:13.220286',NULL),(70,100171,NULL,'2025-08-16 12:50:35.948925',NULL),(71,100172,NULL,'2025-08-16 12:50:51.320325',NULL),(72,100173,NULL,'2025-08-16 12:51:04.786983',NULL),(73,100174,NULL,'2025-08-16 12:51:26.941158',NULL),(74,100175,NULL,'2025-08-16 12:51:37.217349',NULL),(75,100176,'<ol><li>Factors that may cause an abnormal Microalbumin Creatinine ratio (independent of kidney damage) can be physiological like exercise within 24 hours, menstruation, pregnancy, benign postural proteinuria, water consumption &amp; pathological like infection( UTI) , hematuria, fever, marked hyperglycemia, cardiac decompensation, marked hypertension &amp; poor metabolic control.</li><li>A randomly collected urine sample can be used, but is associated with greater variability because of variable urine output &amp; albumin &amp; creatinine excretion. Hence , it is recommended that abnormal results be repeated using first morning sample.&nbsp;</li><li>As per ADA guidelines, 2019: Two to three specimens collected over a period of 3 - 6 months should be abnormal before considering a patient to have albuminuria.&nbsp;</li><li>A high albumin/ creatinine ratio in persons with low muscle mass indicates low urinary creatinine more often than microalbuminuria.</li></ol>','2025-08-16 12:53:31.570496','2025-11-08 14:04:36.184231'),(76,100177,NULL,'2025-08-16 12:54:04.434715',NULL),(77,100178,NULL,'2025-08-16 12:54:27.786695',NULL),(78,100179,'<h4>Interpretation :&nbsp;</h4><p>Elevated values are observed in Pancreatitis, CA Pancreas, Diabetic ketoacidosis, Cholecystitis, Peptic ulcer, Viral hepatitis. Persistant elevated values may suggest necrosis or pseudocyst formation.</p>','2025-08-16 12:54:48.990039','2025-11-25 17:59:55.153115'),(79,100180,NULL,'2025-08-16 12:55:02.996220',NULL),(80,100181,NULL,'2025-08-16 12:55:12.250735',NULL),(81,100182,'<h4>REFERENCE RANGES:&nbsp;</h4><figure class=\"table\"><table><tbody><tr><td><strong>TIME OF COLLECTION</strong></td><td>&nbsp; &nbsp;&nbsp;<strong> REFERENCE RANGE</strong></td></tr><tr><td>7 AM - 10 AM</td><td>&nbsp; &nbsp; &nbsp;201.31 - 536.54 nmol/L</td></tr><tr><td>4 PM - 8 PM</td><td>&nbsp; &nbsp; &nbsp;65.78 - 330.85 nmol/L</td></tr></tbody></table></figure><h4>NOTE:&nbsp;</h4><p>Cortisol exhibits diurnal variation with the highest levels around 6am to 8am after a night\'s rest. The levels of cortisol fall gradually during the day.</p>','2025-08-16 12:55:24.533531','2025-10-17 19:13:09.978985'),(82,100183,NULL,'2025-08-16 12:55:47.862815',NULL),(83,100184,NULL,'2025-08-16 12:56:21.348339',NULL),(84,100185,NULL,'2025-08-16 12:56:39.136393',NULL),(85,100186,NULL,'2025-08-16 12:56:54.221687',NULL),(86,100187,NULL,'2025-08-16 12:57:03.233649',NULL),(87,100188,NULL,'2025-08-16 12:57:20.937412',NULL),(88,100189,NULL,'2025-08-16 12:57:42.343035',NULL),(89,100190,NULL,'2025-08-16 12:58:08.154524',NULL),(90,100191,'<p><strong>Interpretation:&nbsp;</strong></p><ol><li>Measurements of serum iron, TIBC and the percentage of iron saturation of transferring are useful screening tests for iron deficiency anemia.&nbsp;</li><li>However, serum iron exhibits significant diurnal variation and may transiently rise or reach reference values after dietary or iron supplements &amp; post blood transfusion.&nbsp;</li><li>The diagnostic specificity of a low serum iron for iron deficiency is lost in the presence of acute &amp; chronic inflammatory processes as the concentrations of iron and transferring in the serum are significantly affected, and fall rapidly as part of the acute phase response irrespective of the iron stores status in the body.&nbsp;</li><li>Hence, Concurrent measurement of the markers mentioned in the below interpretative table along with serum iron studies improves the diagnostic specificity for iron deficiency anemia &amp; also provides a reliable work up for microcytic hypo chromic anemia.</li><li>Increased ferritin can occur in patients with multiple blood transfusions, hereditary hemochromatosis, anemia of chronic disease, liver diseases, alcoholism, inflammatory conditions, leukemia, Hodgkins disease, some malignancies and COVID 19.&nbsp;</li><li>Decreased ferritin levels are seen in iron deficiency anemia.</li></ol>','2025-08-16 12:58:41.321017','2025-09-10 14:00:43.818128'),(91,100192,NULL,'2025-08-16 12:58:52.382606',NULL),(92,100193,NULL,'2025-08-16 12:59:06.827543',NULL),(93,100194,NULL,'2025-08-16 12:59:21.670976',NULL),(94,100195,NULL,'2025-08-16 12:59:48.207987',NULL),(95,100196,NULL,'2025-08-16 13:02:44.116777',NULL),(96,100197,NULL,'2025-08-16 13:02:59.166602',NULL),(97,100198,NULL,'2025-08-16 13:03:11.147460',NULL),(98,100199,NULL,'2025-08-16 13:05:18.280001',NULL),(99,100200,NULL,'2025-08-16 13:06:53.458724',NULL),(100,100201,NULL,'2025-08-16 13:11:32.287323',NULL),(101,100202,NULL,'2025-08-16 13:11:43.759237',NULL),(102,100203,NULL,'2025-08-16 13:11:57.171855',NULL),(103,100204,NULL,'2025-08-16 13:12:14.090597',NULL),(104,100205,NULL,'2025-08-16 13:13:22.577665',NULL),(105,100206,'<ol><li>SAAG may be falsely low if serum albumin is &lt; 1.1 g/dL or patient is in shock&nbsp;</li><li>SAAG may be falsely high in chylous ascites.</li></ol><figure class=\"table\"><table><tbody><tr><td>SAAG IN g/dL</td><td>&nbsp; CONDITIONS</td></tr><tr><td><p>&gt;1.1</p><p>Transudative ascites &nbsp; &nbsp;&nbsp;</p></td><td>&nbsp; Cirrhosis, Congestive heart failure, Viral hepatitis with hepatic necrosis, Nephritic syndrome, hepatic vein/IVC obstruction, Constrictive pericarditis &amp; Meig’s syndrome</td></tr><tr><td><p>&lt;1.1</p><p>Exudative ascites &nbsp; &nbsp;&nbsp;</p></td><td>&nbsp; TB Peritonitis, Pancreatitis, Myxedema, Peritoneal carcinomatosis, Pseudomyxoma peritonei &amp; Amyloidosis</td></tr></tbody></table></figure><p><strong>COMMENTS:</strong></p><p>Serum albumin ascites gradient (SAAG) is the difference in the concentration of albumin in serum and in ascitic fluid of the same patient. It is the best single method to differentiate an ascitic exudate from a transudate.</p>','2025-08-16 13:13:34.660764','2025-12-23 17:55:37.407183'),(106,100207,NULL,'2025-08-16 13:13:51.039362',NULL),(107,100208,NULL,'2025-08-16 13:14:01.591101',NULL),(108,100209,NULL,'2025-08-16 13:14:34.459614',NULL),(109,100210,NULL,'2025-08-16 13:14:40.811018',NULL),(110,100211,NULL,'2025-08-16 13:14:54.596106',NULL),(111,100212,NULL,'2025-08-16 13:15:06.309074',NULL),(112,100213,NULL,'2025-08-16 13:15:21.765239',NULL),(113,100214,NULL,'2025-08-16 13:15:27.950160',NULL),(114,100215,NULL,'2025-08-16 13:15:36.565526',NULL),(115,100216,NULL,'2025-08-16 13:15:47.169681',NULL),(116,100217,'<p>REFRENCES:</p><p>In individuals without any signs and symptoms of cardiac disease (all ages):</p><ol><li>For values &lt; 125, there is a low risk of heart failure.&nbsp;</li><li>For values &gt;= 125, there is an increased risk of heart failure.&nbsp;</li></ol><p>In patients of type 2 diabetes mellitus without signs and symptoms of cardiac disease (all ages):&nbsp;</p><ol><li>For values &lt; 125, there is a low risk of heart failure but repeat testing is suggested in 12 months.&nbsp;</li><li>For values &gt;= 125, there is an increased risk of heart failure.&nbsp;</li></ol><p>In patients presenting with signs and symptoms of cardiac disease:&nbsp;</p><ol><li>For values &lt; 300, there is a low risk of acute heart failure (all ages).&nbsp;</li><li>There is an increased risk of heart failure for following categories</li></ol><figure class=\"table\"><table><tbody><tr><td>PATIENT\'S AGE (YEARS)</td><td>&nbsp; &nbsp; &nbsp; NT-proBNP value (pg/mL)</td></tr><tr><td>&lt; 50</td><td>&nbsp; &nbsp; &nbsp; &gt; 450</td></tr><tr><td>50-75</td><td>&nbsp; &nbsp; &nbsp; &gt; 900</td></tr><tr><td>&gt; 75</td><td>&nbsp; &nbsp; &nbsp; &gt; 1800</td></tr></tbody></table></figure>','2025-08-16 13:16:00.063975','2025-11-28 16:23:30.151947'),(117,100218,NULL,'2025-08-16 13:16:32.219518',NULL),(118,100219,NULL,'2025-08-16 13:16:43.011585',NULL),(119,100220,NULL,'2025-08-16 13:16:54.827031',NULL),(120,100221,NULL,'2025-08-16 13:17:13.289316',NULL),(121,100222,NULL,'2025-08-16 13:17:22.331132',NULL),(122,100223,NULL,'2025-08-16 13:17:34.680338',NULL),(123,100224,NULL,'2025-08-16 13:17:56.697699',NULL),(124,100225,NULL,'2025-08-16 13:18:10.464974',NULL),(125,100226,NULL,'2025-08-16 13:18:19.388132',NULL),(126,100227,NULL,'2025-08-16 13:19:14.566315',NULL),(127,100228,NULL,'2025-08-16 13:19:21.448940',NULL),(128,100229,NULL,'2025-08-16 13:19:41.661252',NULL),(129,100230,NULL,'2025-08-16 13:21:53.237895',NULL),(130,100231,NULL,'2025-08-16 13:22:39.422445',NULL),(131,100232,NULL,'2025-08-16 13:22:52.757146',NULL),(132,100233,NULL,'2025-08-16 13:23:21.515434',NULL),(133,100234,NULL,'2025-08-16 13:28:03.944963',NULL),(134,100235,NULL,'2025-08-16 15:32:05.854520',NULL),(135,100236,NULL,'2025-08-16 15:32:18.408715',NULL),(136,100237,NULL,'2025-08-16 15:32:28.047185',NULL),(137,100238,NULL,'2025-08-16 15:33:18.049951',NULL),(138,100239,NULL,'2025-08-16 15:33:33.359858',NULL),(139,100240,NULL,'2025-08-16 15:34:33.681393',NULL),(140,100241,NULL,'2025-08-16 15:34:51.608235',NULL),(141,100242,'<p><strong>NOTE:</strong></p><p>Intact PTH has been demonstrated to be labile and is susceptible to fragmentation. This instability depends on both time and temperature.</p>','2025-08-17 21:00:50.392575','2025-08-17 21:15:43.135402'),(142,100243,NULL,'2025-08-21 11:28:37.855725',NULL),(143,100102,NULL,'2025-09-09 19:13:25.606817',NULL),(144,100244,NULL,'2025-09-19 11:23:47.627196',NULL),(145,100245,NULL,'2025-09-23 18:57:46.664644',NULL),(146,100246,'<p><strong>Interpretation :</strong>&nbsp;</p><ol><li>C-peptide levels are decreased in insulin-dependent Type I diabetes.&nbsp;</li><li>C-peptide levels are increased in insulinomas, chronic renal disease, Obesity, and Insulin Resistance. Increased C-peptide levels also rule out exogenous insulin administration.&nbsp;</li></ol><p><strong>Clinical Utility:&nbsp;</strong></p><ol><li>C-peptide aids in the diagnosis and treatment of patients with abnormal insulin secretion.&nbsp;</li><li>C-peptide is an aid in the assessment of a residual β-cell function in the early stages of type 1 diabetes mellitus and for the differential diagnosis of latent autoimmune diabetes of adults (LADA) and type 2 diabetes.&nbsp;</li><li>C-peptide measurements are also used to assess the success of islet transplantation and for monitoring after pancreatectomy. In type 2 DM, high values of C-peptide are associated with a high risk of macro-vascular complications.</li></ol><p><strong>Note:&nbsp;</strong></p><ol><li>C-peptide levels show variation with time, food intake, and insulin administration hence a baseline fasting level and associated insulin and blood glucose levels are advocated.&nbsp;</li><li>In renal impairment, the values of C-peptide may be falsely high.&nbsp;</li><li>Concurrent C-peptide levels are advised in patients on insulin therapy for a long duration as in these patients’ anti-insulin antibodies interfere with insulin assays.</li></ol>','2025-10-02 11:59:10.864099','2025-10-02 12:09:34.816050'),(147,100247,'<h4>Interpretation:</h4><figure class=\"table\"><table><tbody><tr><td><strong>FLUID INTAKE</strong></td><td><strong>REFERENCE (mOsm/kgH2O)</strong></td></tr><tr><td>AVERAGE</td><td>300 - 900</td></tr><tr><td>AFTER 12HR FLUID RESTRICTION &nbsp; &nbsp; &nbsp;</td><td>850 - 1200</td></tr></tbody></table></figure>','2025-10-09 13:54:51.934189','2025-10-09 14:07:34.429229'),(148,100248,NULL,'2025-10-10 11:43:21.507062',NULL),(149,100249,NULL,'2025-10-10 11:45:16.177300',NULL),(150,100250,'<h4>AGE RELATED CSF TOTAL PROTEIN VALUES:</h4><figure class=\"table\"><table><tbody><tr><td>AGE STATE</td><td>RANGE (g/L)</td></tr><tr><td>PREMATURE</td><td>0.15 - 1.30</td></tr><tr><td>FULL TERM NEWBORN</td><td>0.40 - 1.20</td></tr><tr><td>&lt; 1 MONTH</td><td>0.20 - 0.80</td></tr><tr><td>&gt; 1 MONTH</td><td>0.15 - 0.40</td></tr></tbody></table></figure>','2025-10-10 11:46:03.489366','2025-10-13 13:38:23.430631'),(151,100251,NULL,'2025-10-10 13:41:05.626853',NULL),(152,100252,'<h4>Test Description:</h4><ol><li>Autoantibodies against mitochondria (AMA) can be detected in a number of diseases frequently together with<br>other antibodies (e.g. Nuclear dots).</li><li>The determination of these antibodies is of particular significance for the diagnosis of primary biliary liver<br>cirrhosis (PBC).</li><li>AMA are also present in other chronic liver diseases and progressive systematic sclerosis.</li></ol><h4>Technique:</h4><p>BIOCHIP slide using combinations of different histological substrates and Hep-2 cells is used.</p><h4>Associated Tests:</h4><ol><li>SLA (Soluble Liver Antigen) Blot test.</li><li>Autoimmune Hepatitis Profile.</li></ol>','2025-10-28 10:42:43.788332','2025-11-06 14:15:21.569107'),(153,100253,NULL,'2025-10-30 15:03:38.925613',NULL),(154,100254,NULL,'2025-11-08 14:39:31.818805',NULL),(155,100255,NULL,'2025-12-16 10:56:41.929862',NULL),(156,100256,'<p>All positive AFB smears or negative &nbsp;AFB smear cases in patients with a high clinical tuberculosis should be further tested and confirmed using Genexpert.<br><strong>Interpretation:</strong><br>Grading of AFB smear on basis of NTEP recommendation</p><figure class=\"table\"><table><tbody><tr><td><strong>ZN STAINING GRADING (100X OIL IMMERSION OBJECTIVE LENS AND 10X EYE PIECE)</strong></td><td><strong>&nbsp; &nbsp; &nbsp;GRADING</strong></td></tr><tr><td>More than 10 AFB / oil immersion field</td><td>&nbsp; &nbsp; &nbsp;3+</td></tr><tr><td>1-10 AFB / oil immersion field</td><td>&nbsp; &nbsp; &nbsp;2+</td></tr><tr><td>10-99 AFB / 100 oil immersion field</td><td>&nbsp; &nbsp; &nbsp; 1+</td></tr><tr><td>1-9 AFB/100 oil immersion field</td><td>&nbsp; &nbsp; &nbsp;Scanty</td></tr><tr><td>No AFB seen/100 oil immersion field</td><td>&nbsp; &nbsp; &nbsp;NA</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table></figure><p><strong>Note:</strong></p><ol><li>Positive AFB smear results provide a first indication of Mycobacterial infection.</li><li>Smear-positivity and grade indicates relative bacterial burden and correlates with disease presentation.</li><li>A negative AFB smear may mean that no mycobacterial infection is present, or that the mycobacteria were not present in sufficient numbers to be seen under the microscope.</li><li>It does not distinguish between viable and dead organisms nor differentiates species of Mycobacteria.</li></ol>','2026-01-06 19:24:59.199422','2026-01-06 20:09:49.767150'),(157,100257,NULL,'2026-01-07 00:01:06.642822',NULL),(158,100257,NULL,'2026-01-07 00:11:35.235928',NULL),(159,100257,NULL,'2026-01-10 12:23:54.489818',NULL),(160,100258,NULL,'2026-01-10 14:41:41.541116',NULL),(161,100259,NULL,'2026-01-10 21:27:20.309744',NULL),(162,100260,NULL,'2026-01-10 21:31:47.724908',NULL),(163,100261,NULL,'2026-01-10 21:31:47.805050',NULL),(164,100262,'<figure class=\"table\"><table><tbody><tr><td>BIOMETRY</td><td>MEASUREMENT</td><td>GESTATIONAL AGE&nbsp;</td></tr><tr><td>BPD</td><td>11.25</td><td>17 WEEKS , 4 DAYS&nbsp;</td></tr><tr><td>HC&nbsp;</td><td>138.38</td><td>20 WEEKS , 5 DAYS&nbsp;</td></tr><tr><td>AC 1</td><td>389</td><td>40 WEEKS, 6 DAYS&nbsp;</td></tr></tbody></table></figure>','2026-01-10 21:38:12.299921','2026-10-05 11:58:54.823916'),(165,100263,NULL,'2026-01-10 21:38:12.368501',NULL),(166,100264,NULL,'2026-01-10 21:38:12.441350',NULL),(167,100265,NULL,'2026-01-11 10:50:34.974095',NULL),(168,100266,NULL,'2026-01-12 14:48:36.596533',NULL),(169,100267,NULL,'2026-01-13 14:34:16.158252',NULL),(170,100268,NULL,'2026-01-13 17:49:56.503572',NULL),(171,100269,NULL,'2026-02-01 12:35:41.914322',NULL),(172,100270,NULL,'2026-03-30 10:59:33.835596',NULL),(175,200000,NULL,'2026-11-16 09:44:41.578584',NULL);
